export default function ContactForm() {
  async function saveContactMessage(formData: FormData) {
    'use server'

    const name = formData.get('name')
    const email = formData.get('email')
    const message = formData.get('message')

    // FormData is untrusted: this action is reachable by direct POST, so the
    // `required` attributes below can't be relied on.
    const errors: Record<string, string> = {}

    if (typeof name !== 'string' || name.trim() === '') {
      errors.name = 'Name is required'
    }
    if (typeof email !== 'string' || email.trim() === '') {
      errors.email = 'Email is required'
    }
    if (typeof message !== 'string' || message.trim() === '') {
      errors.message = 'Message is required'
    }

    // Return early if the form data is invalid
    if (Object.keys(errors).length > 0) {
      return { errors }
    }

    // Simulate saving the contact message
    console.log('Saving contact message:', {
      name: (name as string).trim(),
      email: (email as string).trim(),
      message: (message as string).trim(),
    })

    return { success: true }
  }

  return (
    <div>
      <h2>Contact Us</h2>

      <form action={saveContactMessage}>
        <input name="name" placeholder="Name" required />
        <input name="email" type="email" placeholder="Email" required />
        <textarea name="message" placeholder="Message" required />
        <button type="submit">Send Message</button>
      </form>
    </div>
  )
}

